.grid {
  display: grid;
  grid-template-columns: minmax(auto, 1fr) minmax(auto, 1fr);
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: 100px;
}

.masonry {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: masonry;
  align-tracks: start;
}

.sidebar { order: -1; }
.main { order: 0; }
.ads { order: 1; }
/* Source: main, sidebar, ads -> visual: sidebar, main, ads */

.flex-centered {
  display: flex;
  justify-content: center;
  align-items: center;
}

.grid-centered {
  display: grid;
  place-items: center;
}

.scroll {
  overflow-y: auto;
  will-change: transform;
  transform: translateZ(0);
}

.layout {
  display: grid;
  grid-template-columns: [content-start] 1fr [content-end];
  grid-template-rows: [header-start] auto [header-end content-start] 1fr [content-end];
}

.cols {
  column-count: 3;
  column-gap: 2rem;
  column-rule: 1px solid #ddd;
}

.card {
  break-inside: avoid;
  page-break-inside: avoid;
}

.flex-wrap {
  display: flex;
  flex-wrap: wrap;
}
.item {
  flex: 1 1 200px;
  min-width: 0;
}

.header { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main { grid-area: main; grid-column: span 2; }

.parent {
  position: relative;
  overflow: hidden;
}
.child {
  position: absolute;
  top: 0;
  right: -20px; /* clips because parent has overflow: hidden */
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

.nav {
  display: flex;
}
.spacer { flex: 1; }
.nav-end { margin-left: auto; }

.flex {
  display: flex;
  justify-content: safe center;
  align-items: safe center;
}

.flex-item {
  flex: 0 0 auto;
  width: intrinsic; /* legacy WebKit */
  width: max-content;
}

.hero {
  grid-column: 1 / -1;
  grid-row: 1 / 3;
}

.scroll-area {
  overflow-y: overlay;
  /* Falls back to auto in browsers without overlay support */
}
